-- ======================================================
-- Database Dump: etl_worldbank
-- Project: Analisis Data Science World Bank ASEAN (2015-2024)
-- 4 Tabel: dim_country, fact_economic_data, fact_education_data, fact_health_data
-- ======================================================

CREATE DATABASE IF NOT EXISTS `etl_worldbank`;
USE `etl_worldbank`;

SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `dim_country`;
CREATE TABLE `dim_country` (
  `id` int NOT NULL AUTO_INCREMENT,
  `country_code` varchar(10) COLLATE utf8mb4_general_ci NOT NULL,
  `country` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `region` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `income_group` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `country_code` (`country_code`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;



DROP TABLE IF EXISTS `fact_economic_data`;
CREATE TABLE `fact_economic_data` (
  `id` int NOT NULL AUTO_INCREMENT,
  `country_code` varchar(10) COLLATE utf8mb4_general_ci NOT NULL,
  `year` int NOT NULL,
  `population` bigint DEFAULT NULL,
  `population_million` decimal(15,2) DEFAULT NULL,
  `gdp` decimal(30,2) DEFAULT NULL,
  `gdp_billion` decimal(20,2) DEFAULT NULL,
  `gdp_per_capita` decimal(20,2) DEFAULT NULL,
  `unemployment_rate` decimal(10,2) DEFAULT NULL,
  `life_expectancy` decimal(10,2) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_eco` (`country_code`,`year`),
  CONSTRAINT `fk_eco_country` FOREIGN KEY (`country_code`) REFERENCES `dim_country` (`country_code`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=51 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;



DROP TABLE IF EXISTS `fact_education_data`;
CREATE TABLE `fact_education_data` (
  `id` int NOT NULL AUTO_INCREMENT,
  `country_code` varchar(10) COLLATE utf8mb4_general_ci NOT NULL,
  `year` int NOT NULL,
  `school_enrollment_primary` decimal(10,2) DEFAULT NULL,
  `school_enrollment_secondary` decimal(10,2) DEFAULT NULL,
  `literacy_rate_adult` decimal(10,2) DEFAULT NULL,
  `govt_expenditure_education` decimal(10,2) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_edu` (`country_code`,`year`),
  CONSTRAINT `fk_edu_country` FOREIGN KEY (`country_code`) REFERENCES `dim_country` (`country_code`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=51 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;



DROP TABLE IF EXISTS `fact_health_data`;
CREATE TABLE `fact_health_data` (
  `id` int NOT NULL AUTO_INCREMENT,
  `country_code` varchar(10) COLLATE utf8mb4_general_ci NOT NULL,
  `year` int NOT NULL,
  `health_expenditure_pct_gdp` decimal(10,2) DEFAULT NULL,
  `health_expenditure_per_capita` decimal(15,2) DEFAULT NULL,
  `infant_mortality_rate` decimal(10,2) DEFAULT NULL,
  `hospital_beds_per_1000` decimal(10,2) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_hlt` (`country_code`,`year`),
  CONSTRAINT `fk_hlt_country` FOREIGN KEY (`country_code`) REFERENCES `dim_country` (`country_code`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=51 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;



SET FOREIGN_KEY_CHECKS = 1;
